using MongoDB.Bson;
using MongoDB.Bson.Serialization.Attributes;

namespace App.Entities;

/// <summary>A document of the "posts" collection.</summary>
[BsonIgnoreExtraElements]
public class Post
{
    [BsonId]
    [BsonGuidRepresentation(GuidRepresentation.Standard)]
    public Guid Id { get; set; }

    [BsonElement("title")]
    public string Title { get; set; } = null!;

    [BsonElement("author")]
    [BsonGuidRepresentation(GuidRepresentation.Standard)]
    public Guid Author { get; set; }

    [BsonElement("published_at")]
    [BsonIgnoreIfNull]
    public DateTime? PublishedAt { get; set; }

    [BsonElement("comments")]
    public List<Post.CommentDocument> Comments { get; set; } = null!;

    /// <summary>A nested document: it is stored with the one that holds it.</summary>
    public class CommentDocument
    {
        [BsonElement("id")]
        [BsonGuidRepresentation(GuidRepresentation.Standard)]
        public Guid Id { get; set; }

        [BsonElement("text")]
        public string Text { get; set; } = null!;

        [BsonElement("marks")]
        [BsonGuidRepresentation(GuidRepresentation.Standard)]
        public List<Guid> Marks { get; set; } = null!;

        /// <summary>The fields this class does not know, which are written back with the list</summary>
        [BsonExtraElements]
        internal BsonDocument? OtherFields { get; set; }
    }
}

