using App.Common;
using App.Entities;

namespace App.Repositories;

/// <summary>Keeps authors rows in memory, for tests and for trying the services without a database.</summary>
public class MemoryAuthorRepository : IAuthorRepository
{
    private readonly Dictionary<string, Author> rows = [];

    /// <summary>The key of a row, as a list of its key values.</summary>
    private static object[] KeyOf(Author row) => [row.Id];

    private static string KeyText(Author row) => string.Join("|", KeyOf(row));

    /// <summary>Orders two keys value by value.</summary>
    private static int Compare(IReadOnlyList<object> a, IReadOnlyList<object> b)
    {
        for (var index = 0; index < a.Count; index++)
        {
            var order = Comparer<object>.Default.Compare(a[index], b[index]);
            if (order != 0) return order;
        }
        return 0;
    }

    private IEnumerable<Author> Visible() =>
        rows.Values.Where(row => true).OrderBy(KeyOf, Comparer<object[]>.Create((a, b) => Compare(a, b)));

    public Task<Author?> FindByIdAsync(Guid id)
    {
        return Task.FromResult(Visible().FirstOrDefault(row => Equals(row.Id, id)));
    }

    public Task<Page<Author>> ListAsync(int offset, int limit)
    {
        var rows = Visible().ToList();
        return Task.FromResult(new Page<Author>(rows.Skip(offset).Take(limit).ToList(), rows.Count, offset, limit));
    }

    public Task<Author> InsertAsync(Author entity)
    {
        rows[KeyText(entity)] = entity;
        return Task.FromResult(entity);
    }

    public Task<Author> UpdateAsync(Author entity)
    {
        rows[KeyText(entity)] = entity;
        return Task.FromResult(entity);
    }

    public Task DeleteAsync(Author entity)
    {
        rows.Remove(KeyText(entity));
        return Task.CompletedTask;
    }
}

