    {
        var found = Visible().FirstOrDefault(row => Equals(row.Id, id));
        if (found is null || (found.Comments?.Count ?? 0) != size) return Task.FromResult<Post?>(null);
        found.Comments = (found.Comments ?? []).Where((_, index) => index != position).ToList();
        return Task.FromResult<Post?>(found);
    }
}

