/// <summary>Operations on authors. Repositories commit every write.</summary>
public class AuthorService(IUnitOfWork unitOfWork)
{
    private readonly IUnitOfWork uow = unitOfWork;

    /// <summary>Checks the values against the rules of the "authors" table, and the rows they point to; throws ValidationFailedException with every problem.</summary>
    private static async Task ValidateAsync(IUnitOfWork uow, Dictionary<string, object?> values, Author? current)
    {
        var creating = current is null;
        var errors = new List<FieldError>();
        {
            var value = values.GetValueOrDefault("Id");
            if (value is null)
                if (creating || values.ContainsKey("Id")) errors.Add(new FieldError("_id", "is required"));
        }
        {
            var value = values.GetValueOrDefault("Email");
            if (value is null)
                if (creating || values.ContainsKey("Email")) errors.Add(new FieldError("email", "is required"));
        }
        if (errors.Count > 0) throw new ValidationFailedException("Author", errors);
    }

    /// <summary>Every check before a write: the values, the rows they point to, the unique values.</summary>
    private static async Task CheckAsync(IUnitOfWork uow, Dictionary<string, object?> values, Author? current)
    {
        await ValidateAsync(uow, values, current);
    }

    /// <summary>Sets the given values on the entity.</summary>
    private static void Apply(Author entity, Dictionary<string, object?> values)
    {
        if (values.TryGetValue("Id", out var id)) entity.Id = (Guid)id!;
        if (values.TryGetValue("Email", out var email)) entity.Email = (string)email!;
    }

    /// <summary>The Author with this key; NotFoundException when there is none.</summary>
    private static async Task<Author> FindAsync(IUnitOfWork uow, Guid id) =>
        await uow.Authors.FindByIdAsync(id) ?? throw new NotFoundException("Author", id);

    /// <summary>The values an update gives, by field.</summary>
    private static Dictionary<string, object?> Given(AuthorChanges changes)
    {
        var values = new Dictionary<string, object?>();
        if (changes.Email is { IsPresent: true } email) values["Email"] = email.Value;
        return values;
    }

    /// <summary>Stores a new Author after checking it.</summary>
    public async Task<Author> CreateAuthorAsync(Author author)
    {
        var values = new Dictionary<string, object?>();
        values["Id"] = author.Id;
        if (author.Email is not null) values["Email"] = author.Email;
        return await this.uow.TransactionAsync(async uow =>
        {
            await CheckAsync(uow, values, null);
            return await uow.Authors.InsertAsync(author);
        });
    }

    /// <summary>The Author with this key; NotFoundException when there is none.</summary>
    public async Task<Author> GetAuthorAsync(Guid id) => await FindAsync(uow, id);

