    public async Task<Page<Author>> ListAuthorsAsync(int offset, int limit) => await uow.Authors.ListAsync(offset, limit);

    /// <summary>Changes the given values of a Author.</summary>
    public async Task<Author> UpdateAuthorAsync(Guid id, AuthorChanges changes)
    {
        var values = Given(changes);
        return await this.uow.TransactionAsync(async uow =>
