    private static async Task ValidateAsync(IUnitOfWork uow, Dictionary<string, object?> values, Post? current)
    {
        var creating = current is null;
        var errors = new List<FieldError>();
        {
            var value = values.GetValueOrDefault("Id");
            if (value is null)
                if (creating || values.ContainsKey("Id")) errors.Add(new FieldError("_id", "is required"));
        }
        {
            var value = values.GetValueOrDefault("Title");
            if (value is null)
                if (creating || values.ContainsKey("Title")) errors.Add(new FieldError("title", "is required"));
        }
        {
            var value = values.GetValueOrDefault("Author");
            if (value is null)
                if (creating || values.ContainsKey("Author")) errors.Add(new FieldError("author", "is required"));
        }
        {
            var value = values.GetValueOrDefault("Comments");
            if (value is null)
            {
                if (creating || values.ContainsKey("Comments")) errors.Add(new FieldError("comments", "is required"));
            }
            else
            {
                var document = (List<Post.CommentDocument>)value;
                if (document is not null)
                {
                    for (var i0 = 0; i0 < document.Count; i0++)
                    {
                        if (document[i0] is null) errors.Add(new FieldError("comments" + "." + i0, "is required"));
                        else CheckComment(document[i0], "comments" + "." + i0, errors);
                    }
                }
            }
        }
        {
            var author = values.TryGetValue("Author", out var givenAuthor) ? (Guid?)givenAuthor : current?.Author;
            if (author is not null && await uow.Authors.FindByIdAsync(author.Value) is null)
                errors.Add(new FieldError("author", "no Author has this key"));
        }
        if (errors.Count > 0) throw new ValidationFailedException("Post", errors);
    }

    /// <summary>Every check before a write: the values, the rows they point to, the unique values.</summary>
    private static async Task CheckAsync(IUnitOfWork uow, Dictionary<string, object?> values, Post? current)
    {
        await ValidateAsync(uow, values, current);
    }

    /// <summary>Sets the given values on the entity.</summary>
    private static void Apply(Post entity, Dictionary<string, object?> values)
    {
        if (values.TryGetValue("Id", out var id)) entity.Id = (Guid)id!;
        if (values.TryGetValue("Title", out var title)) entity.Title = (string)title!;
        if (values.TryGetValue("Author", out var author)) entity.Author = (Guid)author!;
        if (values.TryGetValue("PublishedAt", out var publishedAt)) entity.PublishedAt = (DateTime?)publishedAt;
        if (values.TryGetValue("Comments", out var comments)) entity.Comments = (List<Post.CommentDocument>)comments!;
    }

    /// <summary>The Post with this key; NotFoundException when there is none.</summary>
    private static async Task<Post> FindAsync(IUnitOfWork uow, Guid id) =>
        await uow.Posts.FindByIdAsync(id) ?? throw new NotFoundException("Post", id);

    /// <summary>The values an update gives, by field.</summary>
    private static Dictionary<string, object?> Given(PostChanges changes)
    {
        var values = new Dictionary<string, object?>();
        if (changes.Title is { IsPresent: true } title) values["Title"] = title.Value;
        if (changes.Author is { IsPresent: true } author) values["Author"] = author.Value;
        if (changes.PublishedAt is { IsPresent: true } publishedAt) values["PublishedAt"] = publishedAt.Value;
        if (changes.Comments is { IsPresent: true } comments) values["Comments"] = comments.Value;
        return values;
    }

    /// <summary>What a Post.CommentDocument does not follow of its rules, each with the path of its field.</summary>
    private static void CheckComment(Post.CommentDocument value, string path, List<FieldError> errors)
    {
        if (value.Text is null) errors.Add(new FieldError(path + ".text", "is required"));
        if (value.Marks is null) errors.Add(new FieldError(path + ".marks", "is required"));
    }

    /// <summary>Stores a new Post after checking it.</summary>
    public async Task<Post> CreatePostAsync(Post post)
    {
        var values = new Dictionary<string, object?>();
        values["Id"] = post.Id;
        if (post.Title is not null) values["Title"] = post.Title;
        values["Author"] = post.Author;
        if (post.PublishedAt is not null) values["PublishedAt"] = post.PublishedAt;
        if (post.Comments is not null) values["Comments"] = post.Comments;
        return await this.uow.TransactionAsync(async uow =>
        {
            await CheckAsync(uow, values, null);
            return await uow.Posts.InsertAsync(post);
        });
    }

    /// <summary>The Post with this key; NotFoundException when there is none.</summary>
    public async Task<Post> GetPostAsync(Guid id) => await FindAsync(uow, id);

    /// <summary>A page of posts, by primary key.</summary>
    public async Task<Page<Post>> ListPostsAsync(int offset, int limit) => await uow.Posts.ListAsync(offset, limit);

    /// <summary>Changes the given values of a Post.</summary>
    public async Task<Post> UpdatePostAsync(Guid id, PostChanges changes)
    {
        var values = Given(changes);
        return await this.uow.TransactionAsync(async uow =>
        {
            var current = await FindAsync(uow, id);
            await CheckAsync(uow, values, current);
            Apply(current, values);
            return await uow.Posts.UpdateAsync(current);
        });
    }

    /// <summary>Deletes a Post.</summary>
    public async Task DeletePostAsync(Guid id)
    {
        await this.uow.TransactionAsync(async uow =>
        {
            var current = await FindAsync(uow, id);
            await uow.Posts.DeleteAsync(current);
        });
    }

    /// <summary>The posts with this author.</summary>
    public async Task<List<Post>> ListPostsByAuthorAsync(Guid author) => await uow.Posts.ListByAuthorAsync(author);

    /// <summary>Adds an item to comments.</summary>
    public async Task<Post> AddCommentAsync(Guid id, Post.CommentDocument comment)
    {
        var errors = new List<FieldError>();
        CheckComment(comment, "comments", errors);
        if (errors.Count > 0) throw new ValidationFailedException("Post", errors);
        return await this.uow.TransactionAsync(async uow =>
        {
            await FindAsync(uow, id);
            return await uow.Posts.AddCommentAsync(id, comment) ?? throw new NotFoundException("Post", id);
        });
    }

    /// <summary>Removes an item from comments, by its position.</summary>
    public async Task<Post> RemoveCommentAsync(Guid id, int position)
    {
        return await this.uow.TransactionAsync(async uow =>
        {
            var current = await FindAsync(uow, id);
            if (current.Comments is null || position < 0 || position >= current.Comments.Count) throw new NotFoundException("Comment", position);
            return await uow.Posts.RemoveCommentAsync(id, position, current.Comments.Count) ?? throw new ConflictException("Post", "was changed by someone else since it was read", ["Comments"]);
        });
    }
